/*
 * Helper function: Set error message from C string
 *
 * Converts a C string to Pascal string format and copies to bserror.
 * This ensures consistency - the length prefix is automatically calculated
 * from the string length, preventing manual octal prefix errors.
 *
 * Handles NULL bserror gracefully (some callers may not want error messages).
 */
static void seterrorstring(const char *msg, bigstring bserror) {
    if (bserror == NULL)
        return;
    copyctopstring(msg, bserror);
}

/*
 * Helper: Load an external variable into memory and extract its outline.
 *
 * Handles the type dispatch between outline/script externals (which use
 * opverbinmemory and store the outline directly in variabledata) and menu
 * externals (which use menuverbinmemory_context and store a tysavedmenuinfo
 * record — the outline is inside the menu record at menuoutline).
 *
 * Uses the variable's own hdatabase for the db_context so guest-database
 * externals are loaded with the correct format mode and disk addresses.
 */
static boolean loadoutlinefromexternal(hdlexternalvariable hv, hdloutlinerecord *ho, bigstring bserror) {

    db_context ctx;

    if (db_format_is_legacy_db((**hv).hdatabase)) {
        db_context_init_legacy_read(&ctx, (**hv).hdatabase);
    } else {
        db_context_init(&ctx);
        ctx.database = (**hv).hdatabase;
    }

    if ((**hv).id == idmenuprocessor) {
        if (!menuverbinmemory_context(&ctx, hv)) {
            seterrorstring("could not load menu outline", bserror);
            return false;
        }
    } else {
        if (!opverbinmemory(&ctx, hv)) {
            seterrorstring("could not load outline", bserror);
            return false;
        }
    }

    if ((**hv).variabledata == 0) {
        seterrorstring("target has no outline data", bserror);
        return false;
    }

    if ((**hv).id == idmenuprocessor) {
        hdlmenurecord hmenurecord = (hdlmenurecord)(**hv).variabledata;

        if (hmenurecord == nil || (**hmenurecord).menuoutline == nil) {
            seterrorstring("menu has no outline", bserror);
            return false;
        }

        *ho = (**hmenurecord).menuoutline;
    } else {
        *ho = (hdloutlinerecord)(**hv).variabledata;
    }

    return true;
}

/*
 * Helper function: Get outline from target system (headless mode)
 *
 * In GUI mode, op verbs get the outline from the frontmost window.
 * In headless mode, we get it from the target.get() system.
 *
 * Returns: true if outline was successfully retrieved, false otherwise
 * On error, bserror contains a Pascal string with the error message
 */
static boolean getoutlinefromtarget(hdloutlinerecord *ho, bigstring bserror) {
    hdlhashtable htable;
    bigstring bsname;
    tyvaluerecord val;
    hdlhashnode hnode;
    hdlexternalvariable hv;

    /* Get target from lang.target.get() */
    if (!langgettarget(&htable, bsname)) {
        seterrorstring("no outline target set", bserror);
        return false;
    }

    /* Look up the variable */
    if (!hashtablelookup(htable, bsname, &val, &hnode)) {
        seterrorstring("target variable not found", bserror);
        return false;
    }

    /* Check if it's a table (not an outline) */
    if (langexternalvaltotable(val, &htable, hnode)) {
        seterrorstring("target is not an outline", bserror);
        return false;
    }

    /* Verify it's an external variable type */
    if (val.valuetype != externalvaluetype) {
        seterrorstring("target is not an outline", bserror);
        return false;
    }

    /* Get the external variable handle */
    hv = (hdlexternalvariable)val.data.externalvalue;

    /* Verify handle is valid */
    if (hv == NULL) {
        seterrorstring("target is not an outline", bserror);
        return false;
    }

    /* Verify it's an outline-based processor type.
     * Scripts (idscriptprocessor) and menus (idmenuprocessor) are also outlines
     * internally - they use the same hdloutlinerecord structure. */
    switch ((**hv).id) {
        case idoutlineprocessor:
        case idscriptprocessor:
        case idmenuprocessor:
            break;  /* Valid outline types */
        default:
            seterrorstring("target is not an outline", bserror);
            return false;
    }

    /* Load external into memory and extract its outline record */
    if (!loadoutlinefromexternal(hv, ho, bserror))
        return false;

    return true;
}

/*
 * Helper: Recursively traverse outline and build indented text representation
 *
 * This is the core traversal function for op.getsuboutline().
 * It recursively visits the current node and all its descendants, building
 * an indented text string using handlestream.
 *
 * Parameters:
 * - hnode: Current headline node to process
 * - flindent: If true, indent text by level (for human-readable format)
 * - level: Current indentation level (0 = root)
 * - str: Handlestream to accumulate text output
 *
 * Returns: true on success, false on memory allocation failure
 *
 * Reference: opgetsuboutlinevisit() in Common/source/opverbs.c:2820
 */
static boolean opgetsuboutlinevisit(hdlheadrecord hnode, boolean flindent, long level, handlestream *str) {
    hdlheadrecord nomad = hnode;
    long indent = (flindent ? level : 0);

    /* Write current headline with appropriate indentation */
    if (!writehandlestreamhandleindent(str, (**hnode).headstring, indent))
        return false;

    /* Recursively process all subheads (children) */
    if (opnavigate(right, &nomad)) {
        level++;

        while (true) {
            if (!opgetsuboutlinevisit(nomad, flindent, level, str))
                return false;

            if (!opnavigate(down, &nomad))
                break;
        }
    }

    return true;
}

/*
 * Callback for op.getselectedsuboutlines() - copies marked node and its subtree
 *
 * For each marked node in the outline, this callback copies the entire node
 * (including all subheads) and deposits it into the destination outline.
 *
 * Parameters:
 * - hnode: The marked headline node to copy
 * - refcon: Pointer to hdloutlinerecord (destination outline)
 *
 * Returns: true on success, false on memory allocation failure
 *
 * Reference: opgetselectedsuboutlinesvisit() in Common/source/opverbs.c:3061
 */
static boolean opgetselectedsuboutlinesvisit(hdlheadrecord hnode, ptrvoid refcon) {
    hdloutlinerecord ho = (hdloutlinerecord) refcon;
    hdlheadrecord hcopy;
    hdlheadrecord hbarcursor = (**ho).hbarcursor;

    /* Copy the entire node and its subtree */
    hcopy = opcopyoutline(hnode);

    if (hcopy == nil)
        return false;

    /* Push destination outline onto stack */
    oppushoutline(ho);

    opstartinternalchange();

    /* Deposit the copy as a child of the current cursor position */
    opdeposit(hbarcursor, down, hcopy);

    /* Reset levels for the newly deposited subtree */
    opresetlevels((**hbarcursor).headlinkdown);

    opendinternalchange();

    oppopoutline();

    return true;
}

/*
 * Callback for op.getselection() - stores cursor for each marked node
 *
 * For each marked node in the outline, this callback stores the cursor
 * (hdlheadrecord cast to long) in the list being built.
 *
 * Parameters:
 * - hnode: The marked headline node
 * - refcon: Pointer to hdllistrecord to store cursors
 *
 * Returns: true on success, false on memory allocation failure
 *
 * Reference: opgetselvisit() in Common/source/opverbs.c:2767
 */
static boolean opgetselvisit(hdlheadrecord hnode, ptrvoid refcon) {
    hdllistrecord hlist = (hdllistrecord) refcon;
    tyvaluerecord val;

    /* Cursors are hdlheadrecords, coerced to a long */
    if (!setlongvalue((long) hnode, &val))
        return false;

    /* Add value to list */
    if (!langpushlistval(hlist, nil, &val))
        return false;

    /* Don't let values accumulate in memory */
    disposevaluerecord(val, true);

    return true;
}

/*
 * Callback for op.visitall() - invoked for each node in outline
 *
 * This is called by opvisiteverything() for each headline in the outline.
 * It runs the callback script with the cursor positioned at the current node.
 *
 * Pattern: Based on opvisitallvisit() from Common/source/opverbs.c
 */
typedef struct {
    bigstring scriptname;
    hdloutlinerecord houtline;
} opvisitall_context;

static boolean opvisitall_callback(hdlheadrecord hnode, ptrvoid refcon) {
    opvisitall_context *ctx = (opvisitall_context *)refcon;
    tyvaluerecord vreturned;

    /* Push outline context for this callback - ensures op.* verbs work correctly
     * within the callback script. Note: The outline is already pushed by the caller
     * for opvisiteverything traversal, but we push again here to set cursor position. */
    oppushoutline(ctx->houtline);

    /* Set cursor to current node */
    (**ctx->houtline).hbarcursor = hnode;

    /* Call the callback script */
    if (!langrunscript(ctx->scriptname, NULL, NULL, &vreturned)) {
        /* Log callback failure to help with debugging */
        log_warn(LOG_COMP_OP, "op.visitall callback script failed: %s", stringbaseaddress(ctx->scriptname));
        oppopoutline();
        return false;
    }

    oppopoutline();
    return true;
}

